import math
def priority(task, state, b=0.5, k=0.5, m=5.0, boost=1e6, slo=2.0, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / est * (1.0 + b * ratio)
    if ratio >= slo:
        over = ratio - slo
        return boost * (1.0 + over) + base
    else:
        near = slo - ratio
        return base * (1.0 + math.exp(-near / k)) + 0.1 * math.exp(-near / k)  # tuned (b=0.584,k=0.956,m=2.17,boost=5.21e+05,slo=1.23,eps=1.04e-06)

def priority(task, state, c=2.0, m=1.0, p=0.0, rho=0.0, a=0.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if ratio >= c:
        hard = 1e6 + a * (ratio - c)
    else:
        hard = 0.0
    tier = m if task.tenant == 'premium' else 1.0
    res = 1.0 / (max(task.resource_need, 1e-6) ** rho)
    soft = 1.0 + p * max(0.0, ratio - 0.5 * c)
    return hard + tier * res * soft / est  # tuned (c=0.53,m=0.697,p=0,rho=0,a=0)

def priority(task, state, c=2.0, B=1000000.0, a=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    if wait >= c * est:
        return B + a / est
    return -task.due  # tuned (c=3.02,B=9.4e+05,a=1.01)

import math
def priority(task, state, c=2.0, k=0.5, u=0.5, b=1000000.0,
             map_m=1.0, reduce_m=1.05, join_m=1.1, other_m=1.0):
    est = max(task.estimated_runtime, 1e-6)
    if task.task_type == 'map':
        eff = est * map_m
    elif task.task_type == 'reduce':
        eff = est * reduce_m
    elif task.task_type == 'join':
        eff = est * join_m
    else:
        eff = est * other_m
    eff = max(eff, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = c * est - wait
    if slack <= 0.0:
        return b + 1.0 / eff
    mean_est = max(state.mean_est, 1e-6)
    urgency = math.exp(-slack / max(k * mean_est, 1e-6))
    return (1.0 + u * urgency) / eff

def priority(task, state, c=2.0, alpha=0.5, a=0.01):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    footprint = est * (max(task.resource_need, 1e-6) ** alpha)
    ratio = wait / est
    if ratio >= c:
        overdue = wait - c * est
        return 1e9 + 1.0 / max(footprint, 1e-6) + a * overdue / mean
    return 1.0 / max(footprint, 1e-6)
